/**
 * M6 worker bootstrap: boots the Node-RED flow ONCE (nodes stay alive and
 * wired for the worker's whole lifetime, per the architecture rule), installs
 * a single `Capture` instance against it, builds the real `executeNode`
 * Activity, and registers both with a real `@temporalio/worker` Worker.
 *
 * Exports a plain `createWorker(options)` factory - no CLI wiring here; M7
 * owns turning this into a `bin/node-red-temporal` subcommand.
 *
 * --- Known caveat: at-least-once Activity execution (A2 #1) ---
 * Temporal Activities are at-least-once. If this worker process is killed
 * while `executeNode` is mid-flight against a side-effecting node (e.g. an
 * `http request` node that already sent the HTTP call but the process dies
 * before the Activity resolves), Temporal WILL re-schedule and re-run that
 * same Activity invocation on worker restart, re-firing the side effect.
 * This milestone does not attempt to solve or hide that; it is a known,
 * documented limitation of the MVP recovery model (full demonstration is
 * M8's job, killing the worker BETWEEN Activities, not mid-Activity).
 */

"use strict";

const fs = require("fs");
const { Worker } = require("@temporalio/worker");
const { bootstrap } = require("./bootstrap");
const { Capture } = require("./capture");
const { createExecuteNode } = require("./activities");
const { extractWireGraph, extractNodeMeta } = require("./wireGraph");
// Same `@node-red/util` module bootstrap.js already uses for `redUtil.init`/
// `redUtil.events` - it exposes the `hooks` API Capture.install() needs, so
// no test-only helper (`nr-test-utils`) is pulled into production code.
const redUtil = require("../../../@node-red/util");

const WORKFLOWS_PATH = require.resolve("./workflows.js");
const TASK_QUEUE = "node-red-temporal";
const ADDRESS = process.env.TEMPORAL_ADDRESS || "127.0.0.1:7233";

/**
 * M3: lazily creates (once) and reuses a `@temporalio/client` `Client`
 * connected to `TEMPORAL_ADDRESS` (default 127.0.0.1:7233), mirroring
 * `bin/node-red-temporal`'s `runStart` connection pattern. Required at
 * `require()` time so tests can stub the SDK's own entry point the same
 * way `bin_spec.js`/`worker_spec.js` already stub `@temporalio/client`/
 * `Worker.create`.
 *
 * @returns {Promise<object>} a `@temporalio/client` `Client` instance
 */
async function connectClient() {
    const { Client, Connection } = require("@temporalio/client");
    const connection = await Connection.connect({ address: ADDRESS });
    return new Client({ connection });
}

/**
 * M3: maps one M2 ingress group (`{sourceNodeId, msg, sends}`) into an
 * `initial` pending-queue seed array of `{nodeId, msg}` - one entry per
 * `sends[]` item, using EACH send's own `msg` (not the group's top-level
 * `msg`), since fan-out branches could in principle carry per-destination
 * payloads even though today they're identical.
 *
 * @param {{sourceNodeId:string, msg:object, sends:Array<{port:number, destinationId:string, msg:object}>}} ingress
 * @returns {Array<{nodeId:string, msg:object}>}
 */
function toInitial(ingress) {
    return (ingress.sends || []).map((send) => ({ nodeId: send.destinationId, msg: send.msg }));
}

/**
 * M3: builds the `onIngress` callback wired into `Capture`, which starts a
 * real `executeFlow` Workflow Execution for every autonomous source-node
 * emission (e.g. a scheduled Inject firing on its own - `done(false)` has
 * already suppressed local routing for these inside Capture itself, before
 * this callback ever runs).
 *
 * AC7: if `client.workflow.start()` throws/rejects, the error is caught and
 * logged clearly via `console.error` - it must never become an unhandled
 * rejection, and no false success may be reported. Since local routing is
 * already suppressed unconditionally by Capture, there is no fallback to
 * local Node-RED routing to guard against here; this handler's only job is
 * to make a start failure VISIBLE.
 *
 * @param {function(): Promise<object>} getClient - resolves to a connected `Client`
 * @param {{graph:object, nodeMeta:object, flowVersion:string}} flowInfo
 * @returns {function(object): Promise<void>}
 */
function createOnIngress(getClient, flowInfo) {
    return async function onIngress(ingress) {
        const initial = toInitial(ingress);
        const workflowId = `ingress-${Date.now()}-${Math.random().toString(36).slice(2)}`;
        try {
            const client = await getClient();
            await client.workflow.start("executeFlow", {
                taskQueue: TASK_QUEUE,
                workflowId,
                args: [{
                    graph: flowInfo.graph,
                    nodeMeta: flowInfo.nodeMeta,
                    flowVersion: flowInfo.flowVersion,
                    initial
                }]
            });
        } catch (err) {
            console.error(`[node-red-temporal] failed to start executeFlow workflow for source node "${ingress.sourceNodeId}": ${err && err.message ? err.message : err}`);
        }
    };
}

/**
 * @param {string} flowFilePath - path to a Node-RED flows.json file
 * @param {object} [options]
 * @param {object} [options.bootstrapOptions] - forwarded to `bootstrap()`
 * @param {object} [options.captureOptions] - forwarded to `new Capture()`
 * @param {object} [options.workerOptions] - merged into `Worker.create()` options
 * @returns {Promise<{worker: Worker, handle: object, capture: Capture, stop: function(): Promise<void>}>}
 */
async function createWorker(flowFilePath, options) {
    options = options || {};
    const handle = await bootstrap(flowFilePath, options.bootstrapOptions);

    // M3: graph/nodeMeta for ingress-started workflows. Reads the same flow
    // file bootstrap() already parsed - minimal duplicate read, no threading
    // of flows through bootstrap()'s return value (kept out of scope: see
    // "avoid touching bootstrap.js" in the milestone plan).
    const flows = JSON.parse(fs.readFileSync(flowFilePath, "utf8"));
    const graph = extractWireGraph(flows);
    const nodeMeta = extractNodeMeta(flows);

    // Client connection is lazy and memoized: NOT attempted at createWorker()
    // boot time (the worker must still boot even if Temporal is unreachable,
    // per M7 AC1-3), only on the first actual ingress event, and reused
    // across subsequent ones.
    //
    // issue #12 finding 2: a REJECTED connectClient() must not poison every
    // future ingress attempt for the rest of the worker's lifetime. Clearing
    // `clientPromise` in the `.catch()` means a failed attempt is retried on
    // the NEXT ingress event instead of returning the same rejected promise
    // forever; a successful client is still memoized/reused as before.
    let clientPromise;
    function getClient() {
        if (!clientPromise) {
            clientPromise = connectClient().catch((err) => {
                clientPromise = undefined;
                throw err;
            });
        }
        return clientPromise;
    }

    const captureOptions = Object.assign(
        { onIngress: createOnIngress(getClient, { graph, nodeMeta, flowVersion: handle.flowVersion }) },
        options.captureOptions || {}
    );
    const capture = new Capture(captureOptions);
    capture.install(redUtil);

    const executeNode = createExecuteNode({
        getNode: handle.getNode,
        flowVersion: handle.flowVersion,
        capture
    });

    const worker = await Worker.create(Object.assign(
        {
            workflowsPath: WORKFLOWS_PATH,
            activities: { executeNode },
            taskQueue: TASK_QUEUE
        },
        options.workerOptions || {}
    ));

    return {
        worker,
        handle,
        capture,
        flowVersion: handle.flowVersion,
        async stop() {
            worker.shutdown();
            capture.uninstall();
            await handle.stop();
        }
    };
}

module.exports = { createWorker, WORKFLOWS_PATH, toInitial, createOnIngress };
